CREATE TABLE `customer_favorites` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`customer_id` BIGINT UNSIGNED NOT NULL,`professional_id` BIGINT UNSIGNED NULL,`service_id` BIGINT UNSIGNED NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `customer_favorites_public_id_key` (`public_id`),UNIQUE INDEX `customer_favorites_customer_id_professional_id_key` (`customer_id`,`professional_id`),UNIQUE INDEX `customer_favorites_customer_id_service_id_key` (`customer_id`,`service_id`),INDEX `customer_favorites_tenant_id_customer_id_idx` (`tenant_id`,`customer_id`),CONSTRAINT `customer_favorites_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `customer_favorites_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `customer_favorites_professional_id_fkey` FOREIGN KEY (`professional_id`) REFERENCES `professionals`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `customer_favorites_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `appointment_reviews` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`appointment_id` BIGINT UNSIGNED NOT NULL,`customer_id` BIGINT UNSIGNED NOT NULL,`professional_id` BIGINT UNSIGNED NOT NULL,`service_id` BIGINT UNSIGNED NOT NULL,`rating` TINYINT UNSIGNED NOT NULL,`comment` VARCHAR(1000) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `appointment_reviews_public_id_key` (`public_id`),UNIQUE INDEX `appointment_reviews_appointment_id_key` (`appointment_id`),INDEX `appointment_reviews_tenant_id_customer_id_idx` (`tenant_id`,`customer_id`),INDEX `appointment_reviews_tenant_id_professional_id_idx` (`tenant_id`,`professional_id`),CONSTRAINT `appointment_reviews_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `appointment_reviews_appointment_id_fkey` FOREIGN KEY (`appointment_id`) REFERENCES `appointments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `appointment_reviews_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `appointment_reviews_professional_id_fkey` FOREIGN KEY (`professional_id`) REFERENCES `professionals`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `appointment_reviews_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
